// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOutfit = makeLoadFont('Outfit');
const loadRobotoMono = makeLoadFont('RobotoMono');

// Module-level font loading
const { fontFamily: outfitFont } = loadOutfit();
const { fontFamily: robotoMonoFont } = loadRobotoMono();



export type ComponentNameProps = Record<string, any>;

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#e0e5ec",
  transparentBackground = false,
  durationInSeconds = 5,
  messageText = "You're a coconut & traitor to our people, watch your back!",
  textColor = "#111111",
  cardColor = "rgba(255, 255, 255, 0)",
  depthColor = "#ff3b30",
  username = "Kind_Soul",
  avatarColor = "#007aff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors for background color
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive scaling
  const minDim = Math.min(width, height);
  const padding = minDim * 0.05;
  const cardWidth = width * 0.85;

  // Split text into words for staggered animation
  const words = messageText.split(" ");

  // Animations
  // 1. Card entry spring
  const cardScale = spring({
    fps,
    frame: frame - 5,
    config: {
      damping: 12,
      stiffness: 150,
      mass: 1.2,
    },
  });

  // 2. Card rotation for extra pop
  const cardRotate = interpolate(cardScale, [0, 1], [-8, 0]);

  // 3. 3D Shadow depth extension
  const shadowDepth = spring({
    fps,
    frame: frame - 15,
    config: {
      damping: 15,
      stiffness: 120,
    },
  });

  const shadowOffset = interpolate(shadowDepth, [0, 1], [0, minDim * 0.03]);

  // Faux 3D Shadow construction
  const boxShadow = `${shadowOffset}px ${shadowOffset}px 0px ${depthColor}, ${shadowOffset}px ${shadowOffset}px 0px 4px #000000`;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          fontFamily: outfitFont,
          transition: "none",
        }}
      >
        <div
          style={{
            width: cardWidth,
            backgroundColor: cardColor,
            border: "4px solid #000000",
            borderRadius: "16px",
            padding: `${padding}px`,
            display: "flex",
            flexDirection: "column",
            transform: `scale(${cardScale}) rotate(${cardRotate}deg)`,
            boxShadow: boxShadow,
            transition: "none",
            transformOrigin: "center center",
          }}
        >
          {/* Header / Meta Info */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              marginBottom: "32px",
              borderBottom: "2px solid #00000022",
              paddingBottom: "24px",
              transition: "none",
            }}
          >
            <div
              style={{
                width: "60px",
                height: "60px",
                borderRadius: "50%",
                backgroundColor: avatarColor,
                border: "3px solid #000",
                marginRight: "20px",
                transition: "none",
              }}
            />
            <div style={{ display: "flex", flexDirection: "column", transition: "none" }}>
              <span
                style={{
                  fontFamily: robotoMonoFont,
                  fontWeight: 700,
                  fontSize: "28px",
                  color: textColor,
                  transition: "none",
                }}
              >
                {username}
              </span>
              <span
                style={{
                  fontFamily: robotoMonoFont,
                  fontWeight: 400,
                  fontSize: "20px",
                  color: "#666666",
                  transition: "none",
                }}
              >
                Just now • Forum Alert
              </span>
            </div>
          </div>

          {/* Message Body with Staggered Words */}
          <div
            style={{
              display: "flex",
              flexWrap: "wrap",
              gap: "12px 16px", // row-gap, column-gap
              transition: "none",
            }}
          >
            {words.map((word, i) => {
              // Stagger word pop-ins
              const wordStartFrame = 25 + i * 3;
              const wordPop = spring({
                fps,
                frame: frame - wordStartFrame,
                config: {
                  damping: 10,
                  stiffness: 200,
                  mass: 0.8,
                },
              });

              // Subtle 3D pop for each word
              const wordY = interpolate(wordPop, [0, 1], [40, 0]);
              const wordOpacity = interpolate(wordPop, [0, 0.5, 1], [0, 1, 1]);

              return (
                <span
                  key={i}
                  style={{
                    display: "inline-block",
                    fontSize: "64px",
                    fontWeight: 900,
                    color: textColor,
                    lineHeight: 1.1,
                    textTransform: "uppercase",
                    transform: `translateY(${wordY}px) scale(${wordPop})`,
                    opacity: wordOpacity,
                    // Subtle text shadow for internal 3D effect
                    textShadow: `2px 2px 0px ${depthColor}44`,
                    transition: "none",
                  }}
                >
                  {word}
                </span>
              );
            })}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ComponentName;